class AccessPointRule(TLObject):
    ID = 0X4679B65F
    QUALNAME = "types.accessPointRule"

    def __init__(self, phone_prefix_rules: Any = None, dc_id: Any = None, ips: Any = None) -> None:
        self.phone_prefix_rules = phone_prefix_rules
        self.dc_id = dc_id
        self.ips = ips

    def write(self) -> bytes:
        res = struct.pack('<I', self.ID)
        res += write_string(self.phone_prefix_rules)
        res += write_int(self.dc_id)
        res += write_vector(self.ips, lambda x: x.write() if hasattr(x, 'write') else write_bytes(x))
        return res

    @classmethod
    def read(cls, b: BinaryIO) -> AccessPointRule:
        from aiogram.raw.all import read_tl_object
        phone_prefix_rules = read_string(b)
        dc_id = read_int(b)
        ips = read_vector(b, read_tl_object)
        return AccessPointRule(phone_prefix_rules=phone_prefix_rules, dc_id=dc_id, ips=ips)

class AccountAuthorizationForm(TLObject):
    ID = 0XAD2E1CD8
    QUALNAME = "types.account.authorizationForm"

    def __init__(self, required_types: Any = None, values: Any = None, errors: Any = None, users: Any = None, privacy_policy_url: Any = None) -> None:
        self.required_types = required_types
        self.values = values
        self.errors = errors
        self.users = users
        self.privacy_policy_url = privacy_policy_url

    def write(self) -> bytes:
        flags = 0
        if getattr(self, 'privacy_policy_url', None) is not None and getattr(self, 'privacy_policy_url', None) is not False:
            flags |= (1 << 0)
        res = struct.pack('<I', self.ID)
        res += write_int(flags)
        res += write_vector(self.required_types, lambda x: x.write() if hasattr(x, 'write') else write_bytes(x))
        res += write_vector(self.values, lambda x: x.write() if hasattr(x, 'write') else write_bytes(x))
        res += write_vector(self.errors, lambda x: x.write() if hasattr(x, 'write') else write_bytes(x))
        res += write_vector(self.users, lambda x: x.write() if hasattr(x, 'write') else write_bytes(x))
        if bool(flags & (1 << 0)):
            v = getattr(self, 'privacy_policy_url', None) or ''
            if v is not None:
                res += write_string(v)
        return res

    @classmethod
    def read(cls, b: BinaryIO) -> AccountAuthorizationForm:
        from aiogram.raw.all import read_tl_object
        flags = read_int(b)
        required_types = read_vector(b, read_tl_object)
        values = read_vector(b, read_tl_object)
        errors = read_vector(b, read_tl_object)
        users = read_vector(b, read_tl_object)
        privacy_policy_url = read_string(b) if bool(flags & (1 << 0)) else None
        return AccountAuthorizationForm(required_types=required_types, values=values, errors=errors, users=users, privacy_policy_url=privacy_policy_url)

