class AccountAutoSaveSettings(TLObject):
    ID = 0X4C3E069D
    QUALNAME = "types.account.autoSaveSettings"

    def __init__(self, users_settings: Any = None, chats_settings: Any = None, broadcasts_settings: Any = None, exceptions: Any = None, chats: Any = None, users: Any = None) -> None:
        self.users_settings = users_settings
        self.chats_settings = chats_settings
        self.broadcasts_settings = broadcasts_settings
        self.exceptions = exceptions
        self.chats = chats
        self.users = users

    def write(self) -> bytes:
        res = struct.pack('<I', self.ID)
        res += (self.users_settings.write() if hasattr(self.users_settings, 'write') else write_bytes(self.users_settings))
        res += (self.chats_settings.write() if hasattr(self.chats_settings, 'write') else write_bytes(self.chats_settings))
        res += (self.broadcasts_settings.write() if hasattr(self.broadcasts_settings, 'write') else write_bytes(self.broadcasts_settings))
        res += write_vector(self.exceptions, lambda x: x.write() if hasattr(x, 'write') else write_bytes(x))
        res += write_vector(self.chats, lambda x: x.write() if hasattr(x, 'write') else write_bytes(x))
        res += write_vector(self.users, lambda x: x.write() if hasattr(x, 'write') else write_bytes(x))
        return res

    @classmethod
    def read(cls, b: BinaryIO) -> AccountAutoSaveSettings:
        from aiogram.raw.all import read_tl_object
        users_settings = read_tl_object(b)
        chats_settings = read_tl_object(b)
        broadcasts_settings = read_tl_object(b)
        exceptions = read_vector(b, read_tl_object)
        chats = read_vector(b, read_tl_object)
        users = read_vector(b, read_tl_object)
        return AccountAutoSaveSettings(users_settings=users_settings, chats_settings=chats_settings, broadcasts_settings=broadcasts_settings, exceptions=exceptions, chats=chats, users=users)

