class AccountChatThemes(TLObject):
    ID = 0XBE098173
    QUALNAME = "types.account.chatThemes"

    def __init__(self, hash: Any = None, themes: Any = None, chats: Any = None, users: Any = None, next_offset: Any = None) -> None:
        self.hash = hash
        self.themes = themes
        self.chats = chats
        self.users = users
        self.next_offset = next_offset

    def write(self) -> bytes:
        flags = 0
        if getattr(self, 'next_offset', None) is not None and getattr(self, 'next_offset', None) is not False:
            flags |= (1 << 0)
        res = struct.pack('<I', self.ID)
        res += write_int(flags)
        res += write_long(self.hash)
        res += write_vector(self.themes, lambda x: x.write() if hasattr(x, 'write') else write_bytes(x))
        res += write_vector(self.chats, lambda x: x.write() if hasattr(x, 'write') else write_bytes(x))
        res += write_vector(self.users, lambda x: x.write() if hasattr(x, 'write') else write_bytes(x))
        if bool(flags & (1 << 0)):
            v = getattr(self, 'next_offset', None) or ''
            if v is not None:
                res += write_string(v)
        return res

    @classmethod
    def read(cls, b: BinaryIO) -> AccountChatThemes:
        from aiogram.raw.all import read_tl_object
        flags = read_int(b)
        hash = read_long(b)
        themes = read_vector(b, read_tl_object)
        chats = read_vector(b, read_tl_object)
        users = read_vector(b, read_tl_object)
        next_offset = read_string(b) if bool(flags & (1 << 0)) else None
        return AccountChatThemes(hash=hash, themes=themes, chats=chats, users=users, next_offset=next_offset)

