class InputPeerNotifySettings(TLObject):
    ID = 0XCACB6AE2
    QUALNAME = "types.inputPeerNotifySettings"

    def __init__(self, show_previews: Any = None, silent: Any = None, mute_until: Any = None, sound: Any = None, stories_muted: Any = None, stories_hide_sender: Any = None, stories_sound: Any = None) -> None:
        self.show_previews = show_previews
        self.silent = silent
        self.mute_until = mute_until
        self.sound = sound
        self.stories_muted = stories_muted
        self.stories_hide_sender = stories_hide_sender
        self.stories_sound = stories_sound

    def write(self) -> bytes:
        flags = 0
        if getattr(self, 'show_previews', None) is not None and getattr(self, 'show_previews', None) is not False:
            flags |= (1 << 0)
        if getattr(self, 'silent', None) is not None and getattr(self, 'silent', None) is not False:
            flags |= (1 << 1)
        if getattr(self, 'mute_until', None) is not None and getattr(self, 'mute_until', None) is not False:
            flags |= (1 << 2)
        if getattr(self, 'sound', None) is not None and getattr(self, 'sound', None) is not False:
            flags |= (1 << 3)
        if getattr(self, 'stories_muted', None) is not None and getattr(self, 'stories_muted', None) is not False:
            flags |= (1 << 6)
        if getattr(self, 'stories_hide_sender', None) is not None and getattr(self, 'stories_hide_sender', None) is not False:
            flags |= (1 << 7)
        if getattr(self, 'stories_sound', None) is not None and getattr(self, 'stories_sound', None) is not False:
            flags |= (1 << 8)
        res = struct.pack('<I', self.ID)
        res += write_int(flags)
        if bool(flags & (1 << 0)):
            v = getattr(self, 'show_previews', None)
            if v is not None:
                res += write_bool(v)
        if bool(flags & (1 << 1)):
            v = getattr(self, 'silent', None)
            if v is not None:
                res += write_bool(v)
        if bool(flags & (1 << 2)):
            v = getattr(self, 'mute_until', None) or 0
            if v is not None:
                res += write_int(v)
        if bool(flags & (1 << 3)):
            v = getattr(self, 'sound', None)
            if v is not None:
                res += (v.write() if hasattr(v, 'write') else write_bytes(v))
        if bool(flags & (1 << 6)):
            v = getattr(self, 'stories_muted', None)
            if v is not None:
                res += write_bool(v)
        if bool(flags & (1 << 7)):
            v = getattr(self, 'stories_hide_sender', None)
            if v is not None:
                res += write_bool(v)
        if bool(flags & (1 << 8)):
            v = getattr(self, 'stories_sound', None)
            if v is not None:
                res += (v.write() if hasattr(v, 'write') else write_bytes(v))
        return res

    @classmethod
    def read(cls, b: BinaryIO) -> InputPeerNotifySettings:
        from aiogram.raw.all import read_tl_object
        flags = read_int(b)
        show_previews = read_bool(b) if bool(flags & (1 << 0)) else None
        silent = read_bool(b) if bool(flags & (1 << 1)) else None
        mute_until = read_int(b) if bool(flags & (1 << 2)) else None
        sound = read_tl_object(b) if bool(flags & (1 << 3)) else None
        stories_muted = read_bool(b) if bool(flags & (1 << 6)) else None
        stories_hide_sender = read_bool(b) if bool(flags & (1 << 7)) else None
        stories_sound = read_tl_object(b) if bool(flags & (1 << 8)) else None
        return InputPeerNotifySettings(show_previews=show_previews, silent=silent, mute_until=mute_until, sound=sound, stories_muted=stories_muted, stories_hide_sender=stories_hide_sender, stories_sound=stories_sound)

