    def read(cls, b: BinaryIO) -> InputReplyToMessage:
        from aiogram.raw.all import read_tl_object
        flags = read_int(b)
        reply_to_msg_id = read_int(b)
        top_msg_id = read_int(b) if bool(flags & (1 << 0)) else None
        reply_to_peer_id = read_tl_object(b) if bool(flags & (1 << 1)) else None
        quote_text = read_string(b) if bool(flags & (1 << 2)) else None
        quote_entities = read_vector(b, read_tl_object) if bool(flags & (1 << 3)) else None
        quote_offset = read_int(b) if bool(flags & (1 << 4)) else None
        monoforum_peer_id = read_tl_object(b) if bool(flags & (1 << 5)) else None
        todo_item_id = read_int(b) if bool(flags & (1 << 6)) else None
        poll_option = read_bytes(b) if bool(flags & (1 << 7)) else None
