class Page(TLObject):
    ID = 0X98657F0D
    QUALNAME = "types.page"

    def __init__(self, part: Any = None, rtl: Any = None, v2: Any = None, url: Any = None, blocks: Any = None, photos: Any = None, documents: Any = None, views: Any = None) -> None:
        self.part = part
        self.rtl = rtl
        self.v2 = v2
        self.url = url
        self.blocks = blocks
        self.photos = photos
        self.documents = documents
        self.views = views

    def write(self) -> bytes:
        flags = 0
        if getattr(self, 'part', None):
            flags |= (1 << 0)
        if getattr(self, 'rtl', None):
            flags |= (1 << 1)
        if getattr(self, 'v2', None):
            flags |= (1 << 2)
        if getattr(self, 'views', None) is not None and getattr(self, 'views', None) is not False:
            flags |= (1 << 3)
        res = struct.pack('<I', self.ID)
        res += write_int(flags)
        res += write_string(self.url)
        res += write_vector(self.blocks, lambda x: x.write() if hasattr(x, 'write') else write_bytes(x))
        res += write_vector(self.photos, lambda x: x.write() if hasattr(x, 'write') else write_bytes(x))
        res += write_vector(self.documents, lambda x: x.write() if hasattr(x, 'write') else write_bytes(x))
        if bool(flags & (1 << 3)):
            v = getattr(self, 'views', None) or 0
            if v is not None:
                res += write_int(v)
        return res

    @classmethod
    def read(cls, b: BinaryIO) -> Page:
        from aiogram.raw.all import read_tl_object
        flags = read_int(b)
        part = bool(flags & (1 << 0))
        rtl = bool(flags & (1 << 1))
        v2 = bool(flags & (1 << 2))
        url = read_string(b)
        blocks = read_vector(b, read_tl_object)
        photos = read_vector(b, read_tl_object)
        documents = read_vector(b, read_tl_object)
        views = read_int(b) if bool(flags & (1 << 3)) else None
        return Page(part=part, rtl=rtl, v2=v2, url=url, blocks=blocks, photos=photos, documents=documents, views=views)

