    def __init__(self, full_width: Any = None, allow_scrolling: Any = None, url: Any = None, html: Any = None, poster_photo_id: Any = None, w: Any = None, h: Any = None, caption: Any = None) -> None:
        self.full_width = full_width
        self.allow_scrolling = allow_scrolling
