class ReactionsNotifySettings(TLObject):
    ID = 0X71E4EA58
    QUALNAME = "types.reactionsNotifySettings"

    def __init__(self, messages_notify_from: Any = None, stories_notify_from: Any = None, poll_votes_notify_from: Any = None, sound: Any = None, show_previews: Any = None) -> None:
        self.messages_notify_from = messages_notify_from
        self.stories_notify_from = stories_notify_from
        self.poll_votes_notify_from = poll_votes_notify_from
        self.sound = sound
        self.show_previews = show_previews

    def write(self) -> bytes:
        flags = 0
        if getattr(self, 'messages_notify_from', None) is not None and getattr(self, 'messages_notify_from', None) is not False:
            flags |= (1 << 0)
        if getattr(self, 'stories_notify_from', None) is not None and getattr(self, 'stories_notify_from', None) is not False:
            flags |= (1 << 1)
        if getattr(self, 'poll_votes_notify_from', None) is not None and getattr(self, 'poll_votes_notify_from', None) is not False:
            flags |= (1 << 2)
        res = struct.pack('<I', self.ID)
        res += write_int(flags)
        if bool(flags & (1 << 0)):
            v = getattr(self, 'messages_notify_from', None)
            if v is not None:
                res += (v.write() if hasattr(v, 'write') else write_bytes(v))
        if bool(flags & (1 << 1)):
            v = getattr(self, 'stories_notify_from', None)
            if v is not None:
                res += (v.write() if hasattr(v, 'write') else write_bytes(v))
        if bool(flags & (1 << 2)):
            v = getattr(self, 'poll_votes_notify_from', None)
            if v is not None:
                res += (v.write() if hasattr(v, 'write') else write_bytes(v))
        res += (self.sound.write() if hasattr(self.sound, 'write') else write_bytes(self.sound))
        res += write_bool(self.show_previews)
        return res

    @classmethod
    def read(cls, b: BinaryIO) -> ReactionsNotifySettings:
        from aiogram.raw.all import read_tl_object
        flags = read_int(b)
        messages_notify_from = read_tl_object(b) if bool(flags & (1 << 0)) else None
        stories_notify_from = read_tl_object(b) if bool(flags & (1 << 1)) else None
        poll_votes_notify_from = read_tl_object(b) if bool(flags & (1 << 2)) else None
        sound = read_tl_object(b)
        show_previews = read_bool(b)
        return ReactionsNotifySettings(messages_notify_from=messages_notify_from, stories_notify_from=stories_notify_from, poll_votes_notify_from=poll_votes_notify_from, sound=sound, show_previews=show_previews)

