class StatsPublicForwards(TLObject):
    ID = 0X93037E20
    QUALNAME = "types.stats.publicForwards"

    def __init__(self, count: Any = None, forwards: Any = None, next_offset: Any = None, chats: Any = None, users: Any = None) -> None:
        self.count = count
        self.forwards = forwards
        self.next_offset = next_offset
        self.chats = chats
        self.users = users

    def write(self) -> bytes:
        flags = 0
        if getattr(self, 'next_offset', None) is not None and getattr(self, 'next_offset', None) is not False:
            flags |= (1 << 0)
        res = struct.pack('<I', self.ID)
        res += write_int(flags)
        res += write_int(self.count)
        res += write_vector(self.forwards, lambda x: x.write() if hasattr(x, 'write') else write_bytes(x))
        if bool(flags & (1 << 0)):
            v = getattr(self, 'next_offset', None) or ''
            if v is not None:
                res += write_string(v)
        res += write_vector(self.chats, lambda x: x.write() if hasattr(x, 'write') else write_bytes(x))
        res += write_vector(self.users, lambda x: x.write() if hasattr(x, 'write') else write_bytes(x))
        return res

    @classmethod
    def read(cls, b: BinaryIO) -> StatsPublicForwards:
        from aiogram.raw.all import read_tl_object
        flags = read_int(b)
        count = read_int(b)
        forwards = read_vector(b, read_tl_object)
        next_offset = read_string(b) if bool(flags & (1 << 0)) else None
        chats = read_vector(b, read_tl_object)
        users = read_vector(b, read_tl_object)
        return StatsPublicForwards(count=count, forwards=forwards, next_offset=next_offset, chats=chats, users=users)

