class StickerSet(TLObject):
    ID = 0X2DD14EDC
    QUALNAME = "types.stickerSet"

    def __init__(self, archived: Any = None, official: Any = None, masks: Any = None, emojis: Any = None, text_color: Any = None, channel_emoji_status: Any = None, creator: Any = None, installed_date: Any = None, id: Any = None, access_hash: Any = None, title: Any = None, short_name: Any = None, thumbs: Any = None, thumb_dc_id: Any = None, thumb_version: Any = None, thumb_document_id: Any = None, count: Any = None, hash: Any = None) -> None:
        self.archived = archived
        self.official = official
        self.masks = masks
        self.emojis = emojis
        self.text_color = text_color
        self.channel_emoji_status = channel_emoji_status
        self.creator = creator
        self.installed_date = installed_date
        self.id = id
        self.access_hash = access_hash
        self.title = title
        self.short_name = short_name
        self.thumbs = thumbs
        self.thumb_dc_id = thumb_dc_id
        self.thumb_version = thumb_version
        self.thumb_document_id = thumb_document_id
        self.count = count
        self.hash = hash

    def write(self) -> bytes:
        flags = 0
        if getattr(self, 'archived', None):
            flags |= (1 << 1)
        if getattr(self, 'official', None):
            flags |= (1 << 2)
        if getattr(self, 'masks', None):
            flags |= (1 << 3)
        if getattr(self, 'emojis', None):
            flags |= (1 << 7)
        if getattr(self, 'text_color', None):
            flags |= (1 << 9)
        if getattr(self, 'channel_emoji_status', None):
            flags |= (1 << 10)
        if getattr(self, 'creator', None):
            flags |= (1 << 11)
        if getattr(self, 'installed_date', None) is not None and getattr(self, 'installed_date', None) is not False:
            flags |= (1 << 0)
        if getattr(self, 'thumbs', None) is not None and getattr(self, 'thumbs', None) is not False:
            flags |= (1 << 4)
        if getattr(self, 'thumb_dc_id', None) is not None and getattr(self, 'thumb_dc_id', None) is not False:
            flags |= (1 << 4)
        if getattr(self, 'thumb_version', None) is not None and getattr(self, 'thumb_version', None) is not False:
            flags |= (1 << 4)
        if getattr(self, 'thumb_document_id', None) is not None and getattr(self, 'thumb_document_id', None) is not False:
            flags |= (1 << 8)
        res = struct.pack('<I', self.ID)
        res += write_int(flags)
        if bool(flags & (1 << 0)):
            v = getattr(self, 'installed_date', None) or 0
            if v is not None:
                res += write_int(v)
        res += write_long(self.id)
        res += write_long(self.access_hash)
        res += write_string(self.title)
        res += write_string(self.short_name)
        if bool(flags & (1 << 4)):
            v = getattr(self, 'thumbs', None) or []
            if v is not None:
                res += write_vector(v, lambda x: x.write() if hasattr(x, 'write') else write_bytes(x))
        if bool(flags & (1 << 4)):
            v = getattr(self, 'thumb_dc_id', None) or 0
            if v is not None:
                res += write_int(v)
        if bool(flags & (1 << 4)):
            v = getattr(self, 'thumb_version', None) or 0
            if v is not None:
                res += write_int(v)
        if bool(flags & (1 << 8)):
            v = getattr(self, 'thumb_document_id', None) or 0
            if v is not None:
                res += write_long(v)
        res += write_int(self.count)
        res += write_int(self.hash)
        return res

    @classmethod
    def read(cls, b: BinaryIO) -> StickerSet:
        from aiogram.raw.all import read_tl_object
        flags = read_int(b)
        archived = bool(flags & (1 << 1))
        official = bool(flags & (1 << 2))
        masks = bool(flags & (1 << 3))
        emojis = bool(flags & (1 << 7))
        text_color = bool(flags & (1 << 9))
        channel_emoji_status = bool(flags & (1 << 10))
        creator = bool(flags & (1 << 11))
        installed_date = read_int(b) if bool(flags & (1 << 0)) else None
        id = read_long(b)
        access_hash = read_long(b)
        title = read_string(b)
        short_name = read_string(b)
        thumbs = read_vector(b, read_tl_object) if bool(flags & (1 << 4)) else None
        thumb_dc_id = read_int(b) if bool(flags & (1 << 4)) else None
        thumb_version = read_int(b) if bool(flags & (1 << 4)) else None
        thumb_document_id = read_long(b) if bool(flags & (1 << 8)) else None
        count = read_int(b)
        hash = read_int(b)
        return StickerSet(archived=archived, official=official, masks=masks, emojis=emojis, text_color=text_color, channel_emoji_status=channel_emoji_status, creator=creator, installed_date=installed_date, id=id, access_hash=access_hash, title=title, short_name=short_name, thumbs=thumbs, thumb_dc_id=thumb_dc_id, thumb_version=thumb_version, thumb_document_id=thumb_document_id, count=count, hash=hash)

