class StoryViews(TLObject):
    ID = 0X8D595CD6
    QUALNAME = "types.storyViews"

    def __init__(self, has_viewers: Any = None, views_count: Any = None, forwards_count: Any = None, reactions: Any = None, reactions_count: Any = None, recent_viewers: Any = None) -> None:
        self.has_viewers = has_viewers
        self.views_count = views_count
        self.forwards_count = forwards_count
        self.reactions = reactions
        self.reactions_count = reactions_count
        self.recent_viewers = recent_viewers

    def write(self) -> bytes:
        flags = 0
        if getattr(self, 'has_viewers', None):
            flags |= (1 << 1)
        if getattr(self, 'forwards_count', None) is not None and getattr(self, 'forwards_count', None) is not False:
            flags |= (1 << 2)
        if getattr(self, 'reactions', None) is not None and getattr(self, 'reactions', None) is not False:
            flags |= (1 << 3)
        if getattr(self, 'reactions_count', None) is not None and getattr(self, 'reactions_count', None) is not False:
            flags |= (1 << 4)
        if getattr(self, 'recent_viewers', None) is not None and getattr(self, 'recent_viewers', None) is not False:
            flags |= (1 << 0)
        res = struct.pack('<I', self.ID)
        res += write_int(flags)
        res += write_int(self.views_count)
        if bool(flags & (1 << 2)):
            v = getattr(self, 'forwards_count', None) or 0
            if v is not None:
                res += write_int(v)
        if bool(flags & (1 << 3)):
            v = getattr(self, 'reactions', None) or []
            if v is not None:
                res += write_vector(v, lambda x: x.write() if hasattr(x, 'write') else write_bytes(x))
        if bool(flags & (1 << 4)):
            v = getattr(self, 'reactions_count', None) or 0
            if v is not None:
                res += write_int(v)
        if bool(flags & (1 << 0)):
            v = getattr(self, 'recent_viewers', None) or []
            if v is not None:
                res += write_vector(v, write_long)
        return res

    @classmethod
    def read(cls, b: BinaryIO) -> StoryViews:
        from aiogram.raw.all import read_tl_object
        flags = read_int(b)
        has_viewers = bool(flags & (1 << 1))
        views_count = read_int(b)
        forwards_count = read_int(b) if bool(flags & (1 << 2)) else None
        reactions = read_vector(b, read_tl_object) if bool(flags & (1 << 3)) else None
        reactions_count = read_int(b) if bool(flags & (1 << 4)) else None
        recent_viewers = read_vector(b, read_long) if bool(flags & (1 << 0)) else None
        return StoryViews(has_viewers=has_viewers, views_count=views_count, forwards_count=forwards_count, reactions=reactions, reactions_count=reactions_count, recent_viewers=recent_viewers)

