class Theme(TLObject):
    ID = 0XA00E67D6
    QUALNAME = "types.theme"

    def __init__(self, creator: Any = None, default: Any = None, for_chat: Any = None, id: Any = None, access_hash: Any = None, slug: Any = None, title: Any = None, document: Any = None, settings: Any = None, emoticon: Any = None, installs_count: Any = None) -> None:
        self.creator = creator
        self.default = default
        self.for_chat = for_chat
        self.id = id
        self.access_hash = access_hash
        self.slug = slug
        self.title = title
        self.document = document
        self.settings = settings
        self.emoticon = emoticon
        self.installs_count = installs_count

    def write(self) -> bytes:
        flags = 0
        if getattr(self, 'creator', None):
            flags |= (1 << 0)
        if getattr(self, 'default', None):
            flags |= (1 << 1)
        if getattr(self, 'for_chat', None):
            flags |= (1 << 5)
        if getattr(self, 'document', None) is not None and getattr(self, 'document', None) is not False:
            flags |= (1 << 2)
        if getattr(self, 'settings', None) is not None and getattr(self, 'settings', None) is not False:
            flags |= (1 << 3)
        if getattr(self, 'emoticon', None) is not None and getattr(self, 'emoticon', None) is not False:
            flags |= (1 << 6)
        if getattr(self, 'installs_count', None) is not None and getattr(self, 'installs_count', None) is not False:
            flags |= (1 << 4)
        res = struct.pack('<I', self.ID)
        res += write_int(flags)
        res += write_long(self.id)
        res += write_long(self.access_hash)
        res += write_string(self.slug)
        res += write_string(self.title)
        if bool(flags & (1 << 2)):
            v = getattr(self, 'document', None)
            if v is not None:
                res += (v.write() if hasattr(v, 'write') else write_bytes(v))
        if bool(flags & (1 << 3)):
            v = getattr(self, 'settings', None) or []
            if v is not None:
                res += write_vector(v, lambda x: x.write() if hasattr(x, 'write') else write_bytes(x))
        if bool(flags & (1 << 6)):
            v = getattr(self, 'emoticon', None) or ''
            if v is not None:
                res += write_string(v)
        if bool(flags & (1 << 4)):
            v = getattr(self, 'installs_count', None) or 0
            if v is not None:
                res += write_int(v)
        return res

    @classmethod
    def read(cls, b: BinaryIO) -> Theme:
        from aiogram.raw.all import read_tl_object
        flags = read_int(b)
        creator = bool(flags & (1 << 0))
        default = bool(flags & (1 << 1))
        for_chat = bool(flags & (1 << 5))
        id = read_long(b)
        access_hash = read_long(b)
        slug = read_string(b)
        title = read_string(b)
        document = read_tl_object(b) if bool(flags & (1 << 2)) else None
        settings = read_vector(b, read_tl_object) if bool(flags & (1 << 3)) else None
        emoticon = read_string(b) if bool(flags & (1 << 6)) else None
        installs_count = read_int(b) if bool(flags & (1 << 4)) else None
        return Theme(creator=creator, default=default, for_chat=for_chat, id=id, access_hash=access_hash, slug=slug, title=title, document=document, settings=settings, emoticon=emoticon, installs_count=installs_count)

