        if bool(flags & (1 << 3)):
            v = getattr(self, 'outbox_accent_color', None) or 0
            if v is not None:
                res += write_int(v)
        if bool(flags & (1 << 0)):
            v = getattr(self, 'message_colors', None) or []
            if v is not None:
                res += write_vector(v, write_int)
        if bool(flags & (1 << 1)):
            v = getattr(self, 'wallpaper', None)
            if v is not None:
                res += (v.write() if hasattr(v, 'write') else write_bytes(v))
        return res

