        from aiogram.raw.all import read_tl_object
        flags = read_int(b)
        message_colors_animated = bool(flags & (1 << 2))
        base_theme = read_tl_object(b)
        accent_color = read_int(b)
        outbox_accent_color = read_int(b) if bool(flags & (1 << 3)) else None
        message_colors = read_vector(b, read_int) if bool(flags & (1 << 0)) else None
        wallpaper = read_tl_object(b) if bool(flags & (1 << 1)) else None
        return ThemeSettings(message_colors_animated=message_colors_animated, base_theme=base_theme, accent_color=accent_color, outbox_accent_color=outbox_accent_color, message_colors=message_colors, wallpaper=wallpaper)

