        from aiogram.raw.all import read_tl_object
        flags = read_int(b)
        query_id = read_long(b)
        user_id = read_long(b)
        peer = read_tl_object(b)
        msg_id = read_int(b)
        chat_instance = read_long(b)
        data = read_bytes(b) if bool(flags & (1 << 0)) else None
        game_short_name = read_string(b) if bool(flags & (1 << 1)) else None
        return UpdateBotCallbackQuery(query_id=query_id, user_id=user_id, peer=peer, msg_id=msg_id, chat_instance=chat_instance, data=data, game_short_name=game_short_name)

